'use strict';
let csrf='', me=null, directory=null, deptId=null, view='dashboard', detailId=null, filters={folder:'incoming'}, dashboardFilters={floor:'',unit:''};
const byId=id=>document.getElementById(id);
const $content=()=>byId('content');
const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>s?new Date(s).toLocaleString('ar-SY',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const D=id=>directory?.departments?.find(d=>d.id===id);
const fullname=id=>{const d=D(id);return d?d.name+' – '+d.hospital:'—'};
const statNames={active:'نشطة',completed:'تم إنهاء الرد',closed:'مغلقة'};
