function toast(message,error=false){const el=byId('flash');el.textContent=message;el.className='flash'+(error?' error':'');window.scrollTo({top:0,behavior:'smooth'});setTimeout(()=>{if(el.textContent===message)el.classList.add('hidden')},6500)}
async function api(path,{method='GET',body,upload=false,useDept=true}={}){
 const headers={};if(csrf&&method!=='GET')headers['X-CSRF-Token']=csrf;if(useDept&&deptId)headers['X-Department-Id']=String(deptId);if(body&&!upload)headers['Content-Type']='application/json';
 let r;try{r=await fetch(path,{method,credentials:'same-origin',headers,body:body?(upload?body:JSON.stringify(body)):undefined});byId('connectionFlag').textContent='● متصل';byId('connectionFlag').className='online-pill'}catch(e){byId('connectionFlag').textContent='● غير متصل';byId('connectionFlag').className='online-pill offline-pill';throw Error('تعذّر الوصول للخادم. تحقق من الشبكة، ولم يتم تأكيد تنفيذ الإجراء.')}
 if(r.status===401){showLogin();throw Error('انتهت الجلسة، سجّل الدخول مجدداً')}
 if(!r.ok){let message='خطأ غير معروف';try{const e=await r.json();message=typeof e.detail==='string'?e.detail:JSON.stringify(e.detail)}catch{}throw Error(message)}
 if(r.headers.get('content-type')?.includes('application/json'))return r.json();return r;
}
function showLogin(){byId('loginPage').classList.remove('hidden');byId('mainPage').classList.add('hidden');me=null;csrf=''}
function showMain(){byId('loginPage').classList.add('hidden');byId('mainPage').classList.remove('hidden');byId('currentUser').textContent=me.user.name;byId('adminNav').classList.toggle('hidden',!me.user.is_admin);byId('analyticsNav').classList.toggle('hidden',!me.user.is_admin)}
async function refreshDirectory(){directory=await api('/api/directory',{useDept:false});const ids=directory.memberships.map(m=>m.department_id);if(!ids.includes(deptId))deptId=ids[0]??null;const sel=byId('departmentSelect');sel.innerHTML=ids.length?ids.map(id=>`<option value="${id}">${safe(fullname(id))}</option>`).join(''):'<option value="">لا توجد عضوية في قسم</option>';sel.value=deptId??'';byId('hospitalDeptNav').classList.toggle('hidden',!(directory.managed_hospital_ids||[]).length)}
async function start(){try{me=await api('/api/me',{useDept:false});csrf=me.csrf;showMain();await refreshDirectory();if(!deptId&&(me.user.is_admin||directory.managed_hospital_ids?.length))view=me.user.is_admin?'analytics':'departments';await navigate(view);await refreshNotificationCount()}catch(e){showLogin()}}
