 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{const [folder,status]=b.dataset.filter.split(':');filters={folder,status:['today','carryover','archive'].includes(status)?'':status||'',scope:['today','carryover','archive'].includes(status)?status:'open',floor:dashboardFilters.floor,unit:dashboardFilters.unit};navigate(folder)});
